// Normalizes whichever ATS shape came back into the common job schema.
// See n8n/code-nodes/normalize.mjs for the tested standalone version this
// mirrors — keep the two in sync by hand (n8n Code nodes can't import files).
function stripHtml(html) {
  if (!html) return '';
  const decode = (s) => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ');
  let text = decode(html);
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  return decode(text);
}

const source = $('Load active ATS sources').item.json;
const body = $input.item.json;
const results = [];

if (source.ats_type === 'greenhouse' && Array.isArray(body.jobs)) {
  for (const job of body.jobs) {
    results.push({
      company: source.company_name,
      title: job.title,
      url: job.absolute_url,
      location: job.location?.name || 'Remote/Unspecified',
      comp_text: '',
      posted_at: job.updated_at || null,
      description: stripHtml(job.content),
      source_platform: 'greenhouse',
    });
  }
} else if (source.ats_type === 'lever' && Array.isArray(body)) {
  for (const job of body) {
    results.push({
      company: source.company_name,
      title: job.text,
      url: job.hostedUrl,
      location: job.categories?.location || 'Remote/Unspecified',
      comp_text: job.salaryRange ? `${job.salaryRange.min ?? ''}-${job.salaryRange.max ?? ''} ${job.salaryRange.currency ?? ''}`.trim() : '',
      posted_at: job.createdAt ? new Date(job.createdAt).toISOString() : null,
      description: stripHtml(job.descriptionPlain || job.description),
      source_platform: 'lever',
    });
  }
} else if (source.ats_type === 'ashby' && Array.isArray(body.jobs)) {
  for (const job of body.jobs) {
    results.push({
      company: source.company_name,
      title: job.title,
      url: job.jobUrl,
      location: job.locationName || 'Remote/Unspecified',
      comp_text: job.compensation?.summary || '',
      posted_at: job.publishedAt || null,
      description: stripHtml(job.descriptionPlain || job.description),
      source_platform: 'ashby',
    });
  }
}

return results.map((r) => ({ json: r }));
